// 2. Función para cargar contenido
function loadBlogContent(blogId) {
  console.log('=== DEBUG INICIO ===');
  console.log('Blog ID recibido:', blogId);
  console.log('blogData disponible:', !!blogData);
  console.log('Blog existe en datos:', !!blogData[blogId]);
  
  if (!blogData[blogId]) {
    console.error('Blog no encontrado para ID:', blogId);
    console.log('IDs disponibles:', Object.keys(blogData));
    return;
  }

  const blog = blogData[blogId];
  console.log('Datos del blog:', blog);

  try {
    // Actualizar título en breadcrumb
    const productNameElement = document.getElementById("product-name");
    if (productNameElement) {
      productNameElement.textContent = blog.title;
      console.log('✓ Título breadcrumb actualizado');
    } else {
      console.log('✗ Elemento product-name no encontrado');
    }

    // Actualizar título principal
    const zoneTitleElement = document.querySelector(".zone h1");
    if (zoneTitleElement) {
      zoneTitleElement.textContent = blog.title;
      console.log('✓ Título principal actualizado');
    } else {
      console.log('✗ Elemento .zone h1 no encontrado');
    }

    // Actualizar imagen
    const mainImageElement = document.querySelector(".cont-img img");
    if (mainImageElement) {
      mainImageElement.src = blog.image;
      mainImageElement.alt = blog.title;
      console.log('✓ Imagen actualizada:', blog.image);
    } else {
      console.log('✗ Elemento .cont-img img no encontrado');
    }

    // Actualizar contenido
    const contentElement = document.querySelector(".contex");
    if (contentElement) {
      // Buscar y preservar la sección de compartir
      const shareSection = contentElement.querySelector(".share-section");
      
      // Crear el nuevo contenido
      const contentHtml = blog.content
        .map((paragraph) => `<p>${paragraph}</p>`)
        .join("");
      
      // Actualizar contenido
      contentElement.innerHTML = contentHtml;
      
      // Reintegrar la sección de compartir si existía
      if (shareSection) {
        contentElement.appendChild(shareSection);
      }
      
      console.log('✓ Contenido actualizado');
    } else {
      console.log('✗ Elemento .contex no encontrado');
    }

  } catch (error) {
    console.error('Error al cargar contenido:', error);
  }
  
  console.log('=== DEBUG FIN ===');
}

// 3. Función de inicialización mejorada
function initializeBlog() {
  console.log('Inicializando blog...');
  console.log('URL actual:', window.location.href);
  console.log('Pathname:', window.location.pathname);
  
  // Verificar si estamos en la página correcta
  if (window.location.pathname.includes("blogConte.html")) {
    console.log('Estamos en blogConte.html');
    
    const urlParams = new URLSearchParams(window.location.search);
    const blogId = urlParams.get("blog");
    
    console.log('Parámetro blog:', blogId);
    
    if (blogId) {
      // Pequeño delay para asegurar que el DOM esté completamente cargado
      setTimeout(() => {
        loadBlogContent(blogId);
      }, 100);
    } else {
      console.log('No se encontró parámetro blog en la URL');
    }
  } else {
    console.log('No estamos en blogConte.html');
  }
}

// 4. Event listeners mejorados
document.addEventListener("DOMContentLoaded", function() {
  console.log('DOM completamente cargado');
  initializeBlog();
});

// 5. Event listener adicional por si el DOMContentLoaded ya pasó
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeBlog);
} else {
  initializeBlog();
}